package com.mediconnect.appointment;
import static org.assertj.core.api.Assertions.assertThatThrownBy; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import java.time.*; import java.util.*; import com.mediconnect.appointment.api.CreateAppointmentRequest; import com.mediconnect.appointment.application.*; import com.mediconnect.appointment.domain.*; import com.mediconnect.appointment.infrastructure.*; import com.mediconnect.doctor.domain.DoctorEntity; import com.mediconnect.doctor.infrastructure.DoctorRepository; import com.mediconnect.observability.BusinessMetrics; import com.mediconnect.office.domain.OfficeEntity; import com.mediconnect.office.infrastructure.OfficeRepository; import com.mediconnect.patient.domain.PatientEntity; import com.mediconnect.patient.infrastructure.PatientRepository; import com.mediconnect.shared.exception.AppointmentConflictException; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class) class AppointmentServiceTest { @Mock AppointmentRepository appointmentRepository; @Mock DoctorRepository doctorRepository; @Mock PatientRepository patientRepository; @Mock OfficeRepository officeRepository; @Mock AppointmentMapper mapper; @Mock BusinessMetrics metrics; @Mock PatientEntity patient; @Mock DoctorEntity doctor; @Mock OfficeEntity office; private AppointmentService service; private Instant now; @BeforeEach void setUp(){now=Instant.parse("2026-09-26T17:00:00Z");AppointmentPolicy policy=new AppointmentPolicy(Clock.fixed(now,ZoneOffset.UTC));service=new AppointmentService(appointmentRepository,doctorRepository,patientRepository,officeRepository,mapper,policy,metrics,ZoneId.of("UTC"));} @Test void rejectsOverlappingAppointmentBeforeInsert(){UUID doctorId=UUID.randomUUID();UUID officeId=UUID.randomUUID();Instant start=now.plusSeconds(7200);Instant end=start.plusSeconds(1800);when(patientRepository.findByUserEmailIgnoreCase("patient@example.com")).thenReturn(Optional.of(patient));when(doctorRepository.findByIdForUpdate(doctorId)).thenReturn(Optional.of(doctor));when(doctor.isActive()).thenReturn(true);when(doctor.getId()).thenReturn(doctorId);when(officeRepository.findById(officeId)).thenReturn(Optional.of(office));when(office.isActive()).thenReturn(true);when(appointmentRepository.existsDoctorOverlap(eq(doctorId),eq(start),eq(end),eq(AppointmentStatus.CANCELLED))).thenReturn(true);CreateAppointmentRequest request=new CreateAppointmentRequest(doctorId,officeId,start,end);assertThatThrownBy(()->service.createForPatient("patient@example.com",request)).isInstanceOf(AppointmentConflictException.class);verify(appointmentRepository,never()).save(any(AppointmentEntity.class));} }
